import type { Marketplace } from "./offers";

// A recognized destination is checked here; attribution to the user's account
// still depends on the original link generated by their affiliate program.
export function affiliateUrl(value:string,marketplace?:Marketplace):string {
  let url:URL;
  try {url=new URL(value.trim());}catch {throw new Error("Informe o link HTTPS gerado pelo seu programa de afiliados.");}
  if(url.protocol!=="https:"||url.username||url.password||url.port||url.href.length>4096)throw new Error("Use um link HTTPS oficial, sem usuário, senha ou porta personalizada.");
  const mercado=/(^|\.)(mercadolivre\.com(\.br)?|mercadolibre\.com|meli\.la)$/.test(url.hostname);
  const shopee=/(^|\.)(shopee\.com\.br|shope\.ee)$/.test(url.hostname);
  if(marketplace==="mercado"?!mercado:marketplace==="shopee"?!shopee:!mercado&&!shopee)throw new Error(`Informe um link oficial ${marketplace==="shopee"?"da Shopee":marketplace==="mercado"?"do Mercado Livre":"do Mercado Livre ou da Shopee"}.`);
  return url.href;
}
